---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function ()
    -- Propage les variables de session vers D-Bus/systemd --user : sans ça,
    -- les apps lancées via activation D-Bus/systemd (scopes systemd, comme
    -- VS Code) ne voient pas forcément XDG_CURRENT_DESKTOP même si Hyprland
    -- lui-même l'a — repéré en debuggant pourquoi VS Code ne détectait
    -- jamais gnome-keyring malgré un trousseau qui marchait très bien par
    -- ailleurs (testé avec Brave). Doit tourner avant tout le reste.
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_DESKTOP DESKTOP_SESSION XDG_SESSION_TYPE HYPRLAND_INSTANCE_SIGNATURE DISPLAY SSH_AUTH_SOCK")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_DESKTOP DESKTOP_SESSION XDG_SESSION_TYPE HYPRLAND_INSTANCE_SIGNATURE DISPLAY SSH_AUTH_SOCK")

    -- Réveille fprintd dès la session plutôt que d'attendre le premier
    -- déverrouillage : il tourne en activation D-Bus à la demande et
    -- s'arrête après inactivité, or le redémarrer à froid déclenche un
    -- reset USB du capteur (voir systemd-overrides/fprintd.service.d/)
    -- qui n'a pas le temps de finir avant le prompt d'empreinte. Un appel
    -- D-Bus normal (via fprintd-list) déclenche l'activation sans les
    -- droits root qu'exigerait un "systemctl start" direct sur ce service
    -- système.
    hl.exec_cmd("fprintd-list \"$USER\" >/dev/null 2>&1")

    hl.exec_cmd("waybar")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("sleep 1 && awww img $HOME/Pictures/wallpapers/gruvbox-tranquility.png")
    hl.exec_cmd("hyprsunset --temperature 3600")
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("swaync")
    -- Etat initial des indicateurs custom du buttons-grid swaync (voir
    -- .config/swaync/scripts/, contournement du bug amont #739)
    hl.exec_cmd("sleep 1 && $HOME/.config/swaync/scripts/update-bluetooth-state.sh")
    hl.exec_cmd("sleep 1 && $HOME/.config/swaync/scripts/update-airplane-state.sh")
    hl.exec_cmd("sleep 1 && $HOME/.config/swaync/scripts/update-powerprofile-state.sh")
end)


